update public.content_variants set body_id = $json${"type":"image_interpretation","answer":"Toleransi risiko moderat","options":["Ultra-konservatif","Toleransi risiko moderat","Pencari pertumbuhan agresif","Pedagang spekulatif"],"question":"[IMAGE: Diagram lingkaran menunjukkan alokasi aset: 50% saham, 30% obligasi, 15% uang tunai, 5% emas. Label menunjukkan ini adalah portofolio risiko moderat.]\n\nTipe investor apa yang kemungkinan besar diwakili oleh alokasi aset ini?","difficulty":"intermediate","parameters":{"image_description":"Diagram lingkaran menunjukkan alokasi aset: 50% saham, 30% obligasi, 15% uang tunai, 5% emas. Label menunjukkan ini adalah portofolio risiko moderat."},"explanation":"Pembagian 50/30/15/5 antara saham, obligasi, uang tunai, dan emas mewakili risiko yang seimbang — tidak terlalu konservatif dan tidak terlalu agresif."}$json$::jsonb where id = '1b200afa-12d3-4f87-bbff-d2e2ba6b35bf';
